exercise.solution:
const AuthContext = React.createContext(null);

function AuthProvider({ children }) {
  const [user, setUser] = React.useState(null);

  function login(name, role) {
    setUser({ name, role });
  }

  function logout() {
    setUser(null);
  }

  return (
    <AuthContext.Provider value={{ user, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

function RequireAuth({ role, children }) {
  const { user } = React.useContext(AuthContext);

  if (!user) {
    return <p data-testid="denied">Please log in</p>;
  }

  if (role && user.role !== role) {
    return <p data-testid="denied">Not allowed</p>;
  }

  return <>{children}</>;
}

function Screen() {
  const { login, logout } = React.useContext(AuthContext);

  return (
    <div>
      <button onClick={() => login("Anna", "USER")}>Log in as user</button>
      <button onClick={() => login("Bence", "ADMIN")}>Log in as admin</button>
      <button onClick={logout}>Log out</button>

      <RequireAuth>
        <h2>Dashboard</h2>
      </RequireAuth>

      <RequireAuth role="ADMIN">
        <h2>Admin</h2>
      </RequireAuth>
    </div>
  );
}

// The app wraps everything in the provider so every component can read the auth context.
function App() {
  return (
    <AuthProvider>
      <Screen />
    </AuthProvider>
  );
}
